def canDistribute(nums: list[int], quantity: list[int]) -> bool:
    from collections import Counter
    counts = sorted(list(Counter(nums).values()), reverse=True)
    m = len(quantity)
    quantity.sort(reverse=True)
    submask_sum = [0] * (1 << m)
    for mask in range(1 << m):
        for i in range(m):
            if mask & (1 << i):
                submask_sum[mask] += quantity[i]
    memo = {}
    def dp(idx, mask):
        if mask == (1 << m) - 1: return True
        if idx == len(counts): return False
        state = (idx, mask)
        if state in memo: return memo[state]
        unallocated = ((1 << m) - 1) ^ mask
        submask = unallocated
        while submask > 0:
            if submask_sum[submask] <= counts[idx]:
                if dp(idx + 1, mask | submask):
                    memo[state] = True
                    return True
            submask = (submask - 1) & unallocated
        if dp(idx + 1, mask):
            memo[state] = True
            return True
        memo[state] = False
        return False
    return dp(0, 0)

